DO $rapid_check$
DECLARE bare text[];
BEGIN
  SELECT array_agg(location || ': ' || machine_class || ' ' || machine_name ORDER BY location, machine_class, machine_name) INTO bare
    FROM mhr_records
   WHERE machine_class IN ('2_axis_bar_feed_lathe_with_sub_spindle', '2_axis_lathe', '3_axis_bar_feed_lathe_with_sub_spindle', '3_axis_lathe', '3_axis_mill', '3_axis_router', '4_axis_mill', '5_axis_mill', '5_axis_router', 'deep_bore_machine', 'drill_press', 'gun_drill', 'jig_bore', 'machining_millturn', 'stock_prep_lathe', 'stock_prep_mill') AND NOT COALESCE(specs, '{}'::jsonb) ? 'rapid_traverse_mm_per_min';
  IF bare IS NOT NULL THEN RAISE EXCEPTION 'Cutting machines still without a rapid traverse rate (not in memory/machining/machine): %', bare; END IF;
END $rapid_check$;

